import { Component, OnInit } from '@angular/core';

// ❌ OLD: Zone.js patches setInterval, so every tick triggers change
// detection across the ENTIRE component tree — even components that
// read nothing related to `count`.
@Component({
  selector: 'app-root',
  template: `
    <p>Count: {{ count }}</p>
    <big-tree /> <!-- ❌ OLD: re-checked every second, for nothing -->
  `,
})
export class AppComponent implements OnInit {
  count = 0;

  ngOnInit() {
    // ❌ OLD: zone notifies Angular → full-tree CD on every interval
    setInterval(() => this.count++, 1000);
  }
}

