import { Component, signal } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';
import { provideExperimentalZonelessChangeDetection } from '@angular/core';

// ✅ NEW: Zoneless CD. Signal writes notify only the views that read
// them; the rest of the tree is untouched — no zone, no full traversal.
bootstrapApplication(AppComponent, {
  providers: [provideExperimentalZonelessChangeDetection()], // ✅ NEW
});

@Component({
  selector: 'app-root',
  template: `
    <p>Count: {{ count() }}</p> <!-- ✅ NEW: this binding subscribes to the signal -->
    <big-tree /> <!-- ✅ NEW: not re-checked unless it reads signals -->
  `,
})
export class AppComponent {
  count = signal(0); // ✅ NEW: signal-driven state

  constructor() {
    setInterval(() => this.count.update((c) => c + 1), 1000); // ✅ NEW
  }
}
